// Helpers for loading the golden data in tests/data (generated by tools/make_golden.py).
#pragma once

#include <fstream>
#include <iterator>
#include <map>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

#include "isds/protocol.hpp"

namespace test_data {

inline std::string path(const std::string& name) { return std::string(ISDS_TEST_DATA) + "/" + name; }

inline isds::Bytes read_file(const std::string& name)
{
    std::ifstream in(path(name), std::ios::binary);
    if (!in)
        throw std::runtime_error("cannot open " + path(name));
    return {std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>()};
}

inline isds::Bytes descriptor() { return read_file("descriptor_isds205x_1.1.bin"); }

// Rows of a CSV file with a header line, as column name -> value.
inline std::vector<std::map<std::string, std::string>> read_csv(const std::string& name)
{
    std::ifstream in(path(name));
    if (!in)
        throw std::runtime_error("cannot open " + path(name));
    auto split = [](const std::string& line) {
        std::vector<std::string> cells;
        std::stringstream ss(line);
        for (std::string cell; std::getline(ss, cell, ',');)
            cells.push_back(cell);
        return cells;
    };
    std::string line;
    std::getline(in, line);
    const auto header = split(line);
    std::vector<std::map<std::string, std::string>> rows;
    while (std::getline(in, line)) {
        if (line.empty())
            continue;
        const auto cells = split(line);
        std::map<std::string, std::string> row;
        for (std::size_t i = 0; i < header.size() && i < cells.size(); ++i)
            row[header[i]] = cells[i];
        rows.push_back(std::move(row));
    }
    return rows;
}

}  // namespace test_data
